def transform(grid):
    # The 8 rectangle obscures a portion of a symmetric image. Return its horizontally
    # mirrored counterpart where the block is missing.
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # identify all connected components of the marker color 8
    seen=set()
    for r in range(h):
      for c in range(w):
       if grid[r][c]==8 and (r,c) not in seen:
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
         y,x=stack.pop(); comp.append((y,x))
         for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
          q=(y+dy,x+dx)
          if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]==8 and q not in seen:
           seen.add(q); stack.append(q)
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
        # infer symmetry axis from repeated rows/columns; task patch represents occluded values
        # copy from opposite side across center of whole canvas
        for y in range(r0,r1+1):
         for x in range(c0,c1+1):
          sy=h-1-y; sx=w-1-x
          out[y][x]=grid[sy][sx]
    return out
