def transform(grid):
    # Recover the occluded region using its translationally repeated copy.
    h,w=len(grid),len(grid[0])
    cells=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==8]
    r0,r1=min(r for r,c in cells),max(r for r,c in cells)
    c0,c1=min(c for r,c in cells),max(c for r,c in cells)
    # Determine which of the four symmetries maps the visible frame to itself,
    # then use that mapping for the masked rectangle.
    candidates=[]
    for typ in range(4):
        pairs=[]
        for r in range(h):
            for c in range(w):
                if grid[r][c]!=8:
                    if typ==0: q=(r,w-1-c)
                    elif typ==1: q=(h-1-r,c)
                    elif typ==2: q=(h-1-r,w-1-c)
                    else: q=(c,r)
                    rr,cc=q
                    if 0<=rr<h and 0<=cc<w and grid[rr][cc]!=8:
                        pairs.append(grid[r][c]==grid[rr][cc])
        candidates.append(sum(pairs)/max(1,len(pairs)))
    typ=max(range(4),key=lambda t:candidates[t])
    out=[]
    for r in range(r0,r1+1):
        row=[]
        for c in range(c0,c1+1):
            if typ==0: rr,cc=r,w-1-c
            elif typ==1: rr,cc=h-1-r,c
            elif typ==2: rr,cc=h-1-r,w-1-c
            else: rr,cc=c,r
            row.append(grid[rr][cc])
        out.append(row)
    return out
